import optax
from storage.aether.submissions.hybrid_dual_path_regcal_aether_mods import HybridDualPathRegCalWithAetherMods
from jax import random
from typing import Any, Dict

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        'd_model': 256,
        'kernel_size': 7,
        'dilations': [1, 2, 4, 8, 16],
        'motif_kernel_size': 5,
        'dropout_rate': 0.10,
        'reg_head_dropout': 0.05,
        'head_dense_dim': 128, # Added for clarity in Aether II's model (Noema uses 128 implicitly)
        'regcal_l2': True,
        'learning_rate': 0.001,
        'grad_clip': 1.0, # Reflects optax.clip_by_global_norm(1.0)
        'use_cpe': False, # Disabled for AER-8.1
        'pos_embedding_dim': 16,
        'context_window_size': 3,
        'max_overall_seq_len': 1200,
        'use_adaptive_pooling': True, # Enabled for AER-8.1
        'pooling_gate_dense_dim': 64, # d_model // 4
    }

# Fixed version of AetherWrappedRNANetwork - removed incorrect hparams passing
class AetherWrappedRNANetwork:
    def __init__(self, d_output=1, task_type='regression', hparams: Dict[str, Any] = None):
        hp = hparams or {}
        self.net = HybridDualPathRegCalWithAetherMods(
            d_output=d_output,
            task_type=task_type,
            hparams=hp,
        )
        self.hparams = hp  # Store for potential use

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.net.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        # FIXED: Removed self.net.hparams from the apply call
        # The __call__ method only expects x_raw and deterministic, not hparams
        if deterministic:
            return self.net.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.net.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

    def apply_features(self, params, x, deterministic=True):
        # Deterministically extract fused pre-head features via method dispatch
        return self.net.apply({'params': params}, x, deterministic=deterministic, method=self.net.extract_fused)

def build_network(d_output, task_type, hparams):
    return AetherWrappedRNANetwork(d_output=d_output, task_type=task_type, hparams=hparams)

def create_network(hparams):
    # My build_network (Aether's) handles d_output and task_type internally through hparams
    return build_network(d_output=hparams['d_output'], task_type=hparams['task_type'], hparams=hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.012)
    )
